/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentCopy1Wizard, NDXProdIdentProcedureLine11_RouteVersion), FormControlEventType::Lookup)]
public static void NDXProdIdentProcedureLine11_RouteVersion_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    FormDataSource fds = sender.formRun().dataSource(formDataSourceStr(NDXProdIdentCopy1Wizard, InventTable));
    InventTable inventTable = fds.cursor() as InventTable;

    NDXProdIdent_frm_EventHandler::buildRouteVersionControlLookup(sender, inventTable);

    if (ce)
    {
        ce.CancelSuperCall();
    }
}

