    }
}

/// <summary>
/// PaffH 31.10.23
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentCopy1Wizard, FormButtonCopyAndNextItem), FormControlEventType::Clicked),
 SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void FormButtonCopyAndNextItem_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun thisFormRun = sender.formRun();

    FormDataSource inventTable_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentCopy1Wizard, InventTable));
    FormDataSource nDXProdIdentProcedureLine11_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentCopy1Wizard, NDXProdIdentProcedureLine11));
    FormDataSource nDXProdIdentProcedureLine12_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentCopy1Wizard, NDXProdIdentProcedureLine12));

    //boolean lTest = Box::yesNo('Test?', DialogButton::Yes) == DialogButton::Yes;
    boolean lTest = false;
    NDXProdIdent::copyFrom(inventTable_ds.cursor(), nDXProdIdentProcedureLine11_ds.cursor(), nDXProdIdentProcedureLine12_ds.cursor(), lTest);
}
